// ui_toolbar.js
const STATE = require('STATE')
const statedb = STATE(__filename)
const { get } = statedb(fallback_module)
const net = require('net_helper')

module.exports = ui_toolbar

async function ui_toolbar (opts, protocol) {
  const { id, sdb } = await get(opts.sid)
  const { drive } = sdb

  const on = {
    style: inject,
    icons: iconject
  }

  const { io } = net(id)

  const el = document.createElement('div')
  const shadow = el.attachShadow({ mode: 'closed' })

  shadow.innerHTML = `
    <div class="ui-toolbar">
      <div class="toolbar-content">
        <div class="toolbar-left">
          <span class="label">All Component</span>
        </div>

        <div class="toolbar-right">
          <button class="icon-btn btn-close"></button>
          <button class="icon-btn btn-swap"></button>
        </div>
      </div>
     
      <div class="user-profile">
        <div class="avatar"></div>
        <span class="dropdown-icon"></span>
      </div>
    </div>
  `

  const sheet = new CSSStyleSheet()
  shadow.adoptedStyleSheets = [sheet]

  const btn_close = shadow.querySelector('.btn-close')
  const btn_swap = shadow.querySelector('.btn-swap')
  const dropdown_icon = shadow.querySelector('.dropdown-icon')

  const send = protocol
    ? protocol(msg => {
        console.log('[ui_toolbar] message from parent ->', msg)
      })
    : null

  btn_swap.onclick = () => {
    if (send) {
      send({
        type: 'toggle_components'
      })
    }
  }

  btn_close.onclick = () => {
    if (send) {
      send({
        type: 'close'
      })
    }
  }

  await sdb.watch(onbatch)

  return el

  async function onbatch (batch) {
    for (const { type, paths } of batch) {
      const data = await Promise.all(
        paths.map(path => drive.get(path).then(file => file.raw))
      )

      const handler = on[type] || (() => {})
      handler({ data })
    }
  }

  function inject ({ data }) {
    sheet.replaceSync(data[0])
  }

  function iconject ({ data }) {
    const [close_svg = '', swap_svg = '', dropdown_svg = ''] = data

    btn_close.innerHTML = close_svg
    btn_swap.innerHTML = swap_svg
    dropdown_icon.innerHTML = dropdown_svg
  }
}

function fallback_module () {
  return {
    api: fallback_instance,
    _: {
      net_helper: { $: '' }
    }
  }

  function fallback_instance () {
    return {
      _: {
        net_helper: { 0: '' },
        ui_toolbar: {
          mapping: {
            style: 'style',
            icons: 'icons'
          }
        }
      },

      drive: {
        'icons/': {
          'close.svg': { '$ref': 'close.svg' },
          'swap.svg': { '$ref': 'swap.svg' },
          'chevron-down.svg': { '$ref': 'chevron-down.svg' }
        },

        'style/ui_toolbar.css': {
          '$ref': 'ui_toolbar.css'
        }
      }
    }
  }
}